-- Original application tables for the desktop storage foundation.
-- Append future migrations; do not edit an applied migration.


CREATE TABLE xianyu_account (
	id INTEGER NOT NULL,
	platform VARCHAR(50),
	external_uid VARCHAR(200),
	nickname VARCHAR(200),
	avatar_url TEXT,
	province VARCHAR(100),
	city VARCHAR(100),
	account_level VARCHAR(50),
	introduction TEXT,
	followers INTEGER,
	following INTEGER,
	sold_count INTEGER,
	review_num INTEGER,
	seller_level VARCHAR(50),
	praise_ratio VARCHAR(20),
	fish_shop_score DECIMAL(3, 1),
	fish_shop_user SMALLINT,
	remark TEXT,
	status SMALLINT,
	deleted SMALLINT,
	created_time DATETIME,
	updated_time DATETIME,
	PRIMARY KEY (id)
);

CREATE TABLE xianyu_account_auth (
	id INTEGER NOT NULL,
	account_id BIGINT NOT NULL,
	encrypted_cookie TEXT,
	encrypted_token TEXT,
	login_username VARCHAR(255),
	encrypted_login_password TEXT,
	show_browser BOOLEAN,
	cookie_status SMALLINT,
	ws_token TEXT,
	token_expire_time DATETIME,
	last_login_status_code VARCHAR(64),
	last_login_status_message VARCHAR(255),
	last_login_check_time DATETIME,
	deleted SMALLINT,
	created_time DATETIME,
	updated_time DATETIME,
	PRIMARY KEY (id)
);

CREATE TABLE xianyu_account_runtime (
	id INTEGER NOT NULL,
	account_id BIGINT NOT NULL,
	online_status SMALLINT,
	ws_status SMALLINT,
	ws_latency_ms INTEGER,
	cookie_status SMALLINT,
	last_login_status_code VARCHAR(64),
	last_login_status_message VARCHAR(255),
	last_login_check_time DATETIME,
	last_login_time DATETIME,
	last_heartbeat_time DATETIME,
	last_online_time DATETIME,
	last_sync_time DATETIME,
	deleted SMALLINT,
	created_time DATETIME,
	updated_time DATETIME,
	PRIMARY KEY (id)
);

CREATE TABLE xianyu_goods (
	id INTEGER NOT NULL,
	account_id BIGINT,
	goods_id VARCHAR(100),
	external_goods_id VARCHAR(100),
	title VARCHAR(500),
	price VARCHAR(50),
	sold_price VARCHAR(50),
	cover_pic TEXT,
	image_url TEXT,
	image_urls JSON,
	stock INTEGER,
	quantity INTEGER,
	exposure_count INTEGER,
	view_count INTEGER,
	want_count INTEGER,
	detail_url TEXT,
	detail_info TEXT,
	description TEXT,
	raw_payload JSON,
	category VARCHAR(100),
	sort_order INTEGER,
	status SMALLINT,
	deleted SMALLINT,
	auto_reply_enabled SMALLINT,
	auto_relist_enabled SMALLINT NOT NULL,
	has_snapshot SMALLINT NOT NULL,
	original_quantity INTEGER,
	next_relist_goods_id BIGINT,
	relist_source_goods_id BIGINT,
	last_relist_at DATETIME,
	created_time DATETIME,
	updated_time DATETIME,
	PRIMARY KEY (id)
);

CREATE TABLE xianyu_trade_order (
	id INTEGER NOT NULL,
	account_id BIGINT,
	external_order_id VARCHAR(200),
	order_status SMALLINT,
	total_amount VARCHAR(50),
	buyer_name VARCHAR(200),
	buyer_id VARCHAR(200),
	create_time DATETIME,
	pay_time DATETIME,
	ship_time DATETIME,
	confirm_time DATETIME,
	buyer_message TEXT,
	item_id VARCHAR(100),
	is_bargain SMALLINT,
	is_rated SMALLINT,
	is_red_flower SMALLINT,
	deleted SMALLINT,
	created_time DATETIME,
	updated_time DATETIME,
	PRIMARY KEY (id)
);

CREATE TABLE xianyu_trade_order_item (
	id INTEGER NOT NULL,
	order_id BIGINT NOT NULL,
	goods_id BIGINT,
	goods_name VARCHAR(300),
	goods_title VARCHAR(500),
	goods_image TEXT,
	goods_price DECIMAL(12, 2),
	price_cent BIGINT,
	goods_count INTEGER,
	quantity INTEGER,
	subtotal_cent BIGINT,
	sku_id VARCHAR(100),
	sku_name VARCHAR(200),
	deleted SMALLINT,
	created_time DATETIME,
	updated_time DATETIME,
	PRIMARY KEY (id)
);

CREATE TABLE delivery_rule (
	id INTEGER NOT NULL,
	account_id BIGINT,
	rule_name VARCHAR(200),
	goods_id BIGINT,
	delivery_mode VARCHAR(50),
	card_group_id BIGINT,
	delivery_content TEXT,
	trigger_on_pay SMALLINT,
	trigger_keyword VARCHAR(200),
	max_delivery_per_day INTEGER,
	status SMALLINT,
	deleted SMALLINT,
	created_time DATETIME,
	updated_time DATETIME,
	PRIMARY KEY (id)
);

CREATE TABLE card_group (
	id INTEGER NOT NULL,
	group_name VARCHAR(200) NOT NULL,
	group_type VARCHAR(50),
	total_count INTEGER,
	used_count INTEGER,
	available_count INTEGER,
	remark TEXT,
	status SMALLINT,
	deleted SMALLINT,
	created_time DATETIME,
	updated_time DATETIME,
	PRIMARY KEY (id)
);

CREATE TABLE card_item (
	id INTEGER NOT NULL,
	group_id BIGINT NOT NULL,
	card_key TEXT NOT NULL,
	card_value TEXT,
	extra_info TEXT,
	status SMALLINT,
	used_order_id BIGINT,
	realtime_attempt_id BIGINT,
	claim_token VARCHAR(64),
	is_used SMALLINT,
	used_time DATETIME,
	used_by_order_id BIGINT,
	used_by_user VARCHAR(200),
	expire_time DATETIME,
	remark TEXT,
	deleted SMALLINT,
	created_time DATETIME,
	updated_time DATETIME,
	PRIMARY KEY (id)
);

CREATE TABLE delivery_record (
	id INTEGER NOT NULL,
	account_id BIGINT,
	order_id BIGINT,
	rule_id BIGINT,
	delivery_type VARCHAR(50),
	delivery_mode VARCHAR(50),
	content TEXT,
	delivery_content TEXT,
	receiver_info TEXT,
	delivery_timing VARCHAR(50),
	status SMALLINT,
	delivery_status VARCHAR(50),
	error_message TEXT,
	retry_count INTEGER,
	fail_reason TEXT,
	delivery_time DATETIME,
	completed_time DATETIME,
	quantity_requested INTEGER,
	quantity_sent INTEGER,
	platform_sync_time DATETIME,
	result TEXT,
	deleted SMALLINT,
	created_time DATETIME,
	updated_time DATETIME,
	PRIMARY KEY (id)
);
